import{_ as a,o as e,c as n,a3 as i}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Agent 设计模式","description":"以控制权如何分配为主线，比较直接调用、工具循环、路由、计划执行、审查修订和工作流内 Agent。","frontmatter":{"title":"Agent 设计模式","description":"以控制权如何分配为主线，比较直接调用、工具循环、路由、计划执行、审查修订和工作流内 Agent。","framework":"LangChain v1 / LangGraph","version":"Python 3.12 / langchain 1.3.x","verified_at":"2026-07-29","source":["https://docs.langchain.com/oss/python/langchain/agents","https://docs.langchain.com/oss/python/langchain/context-engineering","https://docs.langchain.com/oss/python/langchain/middleware/overview"],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"py-agent/agent/design-practice/agent-design-patterns.md","filePath":"py-agent/agent/design-practice/agent-design-patterns.md","lastUpdated":1785314595000}'),l={name:"py-agent/agent/design-practice/agent-design-patterns.md"};function d(s,t,r,h,o,p){return e(),n("div",null,[...t[0]||(t[0]=[i(`<h1 id="agent-设计模式" tabindex="-1">Agent 设计模式 <a class="header-anchor" href="#agent-设计模式" aria-label="Permalink to &quot;Agent 设计模式&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>Agent 模式不是按框架类名分类，而是按“下一步行动的控制权如何分配”分类。控制权越多交给模型，系统越能应对开放任务，但成本、延迟和失败空间也越大。设计时应从最少控制权的方案开始。</p><h2 id="_1-先判断是否需要-agent" tabindex="-1">1. 先判断是否需要 Agent <a class="header-anchor" href="#_1-先判断是否需要-agent" aria-label="Permalink to &quot;1. 先判断是否需要 Agent&quot;">​</a></h2><p>以下任务通常不需要 Agent：</p><ul><li>输入经过一次模型转换就能完成；</li><li>步骤和分支可以完整列出；</li><li>工具调用顺序由业务规则决定；</li><li>高风险操作必须严格按状态机执行；</li><li>输出主要是固定字段抽取或分类。</li></ul><p>这些任务使用模型调用、结构化输出或确定性工作流更容易测试。只有“下一步做什么”无法在编码时完全确定，且模型确实可以利用语义做出有效选择时，Agent 循环才有价值。</p><h2 id="_2-统一比较轴" tabindex="-1">2. 统一比较轴 <a class="header-anchor" href="#_2-统一比较轴" aria-label="Permalink to &quot;2. 统一比较轴&quot;">​</a></h2><p>本文只用一个主轴比较模式：<strong>谁决定下一步行动</strong>。</p><table tabindex="0"><thead><tr><th>模式</th><th>下一步由谁决定</th><th>自由度</th><th>主要代价</th></tr></thead><tbody><tr><td>直接模型调用</td><td>应用固定</td><td>低</td><td>无法主动使用外部能力</td></tr><tr><td>工具型 Agent</td><td>模型在工具集合中选择</td><td>中</td><td>循环、误选、工具风险</td></tr><tr><td>路由</td><td>模型或规则选择一个处理分支</td><td>中</td><td>路由错误和分支维护</td></tr><tr><td>计划—执行</td><td>模型先计划，再逐步执行</td><td>高</td><td>计划失效和额外调用</td></tr><tr><td>审查—修订</td><td>模型或独立规则决定是否返工</td><td>高</td><td>可能无限修订、成本高</td></tr><tr><td>工作流内 Agent</td><td>工作流固定阶段，Agent 控制局部</td><td>可控</td><td>两套控制语义需要协调</td></tr></tbody></table><p>模式不是成熟度等级。更复杂的模式只有在简单方案无法满足指标时才值得采用。</p><h2 id="_3-模式一-直接模型调用" tabindex="-1">3. 模式一：直接模型调用 <a class="header-anchor" href="#_3-模式一-直接模型调用" aria-label="Permalink to &quot;3. 模式一：直接模型调用&quot;">​</a></h2><p>控制流由应用固定：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入 -&gt; 模型 -&gt; 结构化校验 -&gt; 输出</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>适合摘要、改写、抽取、分类和单轮问答。它没有自主工具循环，但仍可以在调用前检索数据、在调用后执行确定性业务逻辑。</p><h3 id="_3-1-选择条件" tabindex="-1">3.1 选择条件 <a class="header-anchor" href="#_3-1-选择条件" aria-label="Permalink to &quot;3.1 选择条件&quot;">​</a></h3><ul><li>一次调用即可获得足够结果；</li><li>不需要模型动态决定工具；</li><li>失败可以通过 Schema、重试或人工处理；</li><li>对延迟和成本敏感。</li></ul><h3 id="_3-2-常见误判" tabindex="-1">3.2 常见误判 <a class="header-anchor" href="#_3-2-常见误判" aria-label="Permalink to &quot;3.2 常见误判&quot;">​</a></h3><p>“使用了大模型”不等于“使用了 Agent”。把一次分类调用包装成 Agent 只会增加概念和运行开销。</p><h2 id="_4-模式二-工具型-agent" tabindex="-1">4. 模式二：工具型 Agent <a class="header-anchor" href="#_4-模式二-工具型-agent" aria-label="Permalink to &quot;4. 模式二：工具型 Agent&quot;">​</a></h2><p>模型在每轮判断是直接回答、调用哪个工具，还是根据结果继续调用：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户请求 -&gt; 模型 &lt;-&gt; 工具 -&gt; 最终回答</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这是 <code>create_agent()</code> 的核心模式，适合信息查询、诊断和受控操作。</p><h3 id="_4-1-选择条件" tabindex="-1">4.1 选择条件 <a class="header-anchor" href="#_4-1-选择条件" aria-label="Permalink to &quot;4.1 选择条件&quot;">​</a></h3><ul><li>用户表达开放，但候选能力有限；</li><li>工具选择和参数可以由语义决定；</li><li>工具结果会影响下一步；</li><li>每个工具都有清楚契约和安全边界。</li></ul><h3 id="_4-2-主要风险" tabindex="-1">4.2 主要风险 <a class="header-anchor" href="#_4-2-主要风险" aria-label="Permalink to &quot;4.2 主要风险&quot;">​</a></h3><ul><li>工具过多导致误选；</li><li>参数表面合法但业务无效；</li><li>模型反复调用同一工具；</li><li>副作用在最终回答前已经发生；</li><li>工具错误被模型掩盖或猜测。</li></ul><p>应通过动态工具集合、Runtime Context 授权、调用预算和审计控制这些风险。</p><h2 id="_5-模式三-路由" tabindex="-1">5. 模式三：路由 <a class="header-anchor" href="#_5-模式三-路由" aria-label="Permalink to &quot;5. 模式三：路由&quot;">​</a></h2><p>路由先判断请求属于哪个稳定分支，再由该分支处理：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请求 -&gt; 路由器 -&gt; 订单分支</span></span>
<span class="line"><span>                -&gt; 账户分支</span></span>
<span class="line"><span>                -&gt; 通用问答分支</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>路由与工具型 Agent 的区别是：路由通常选择一次处理路径，工具型 Agent 可以在循环中多次选择能力。</p><h3 id="_5-1-规则路由还是模型路由" tabindex="-1">5.1 规则路由还是模型路由 <a class="header-anchor" href="#_5-1-规则路由还是模型路由" aria-label="Permalink to &quot;5.1 规则路由还是模型路由&quot;">​</a></h3><table tabindex="0"><thead><tr><th>条件</th><th>推荐方式</th></tr></thead><tbody><tr><td>字段、状态或权限可以明确判断</td><td>确定性规则</td></tr><tr><td>意图依赖自然语言语义</td><td>模型结构化分类</td></tr><tr><td>高风险分支</td><td>模型给候选，规则再次确认</td></tr></tbody></table><p>模型路由应输出有限枚举，并提供 <code>unknown</code> 或人工处理分支。不要让模型生成任意模块名再动态导入代码。</p><h2 id="_6-模式四-计划—执行" tabindex="-1">6. 模式四：计划—执行 <a class="header-anchor" href="#_6-模式四-计划—执行" aria-label="Permalink to &quot;6. 模式四：计划—执行&quot;">​</a></h2><p>计划—执行先把开放目标拆为步骤，再逐步执行和更新计划：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目标 -&gt; 计划 -&gt; 执行步骤 -&gt; 观察结果 -&gt; 更新计划 -&gt; 完成</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>适合跨多个信息源、需要多步探索且初始顺序不完全确定的任务。简单的两步工具调用通常不值得增加规划层。</p><h3 id="_6-1-计划不是事实" tabindex="-1">6.1 计划不是事实 <a class="header-anchor" href="#_6-1-计划不是事实" aria-label="Permalink to &quot;6.1 计划不是事实&quot;">​</a></h3><p>计划只是当前假设，必须包含：</p><ul><li>每步目标和成功条件；</li><li>允许使用的工具；</li><li>依赖的前置结果；</li><li>预算和停止条件；</li><li>失败后是重试、改计划还是终止。</li></ul><p>如果工具执行改变外部状态，计划步骤还需明确确认和幂等策略。</p><h3 id="_6-2-主要风险" tabindex="-1">6.2 主要风险 <a class="header-anchor" href="#_6-2-主要风险" aria-label="Permalink to &quot;6.2 主要风险&quot;">​</a></h3><p>计划可能基于错误前提，执行结果也可能使后续步骤失效。系统需要在每步后重新校验，而不是盲目执行模型最初列出的清单。</p><h2 id="_7-模式五-审查—修订" tabindex="-1">7. 模式五：审查—修订 <a class="header-anchor" href="#_7-模式五-审查—修订" aria-label="Permalink to &quot;7. 模式五：审查—修订&quot;">​</a></h2><p>初稿生成后，由规则或审查器指出具体问题，再决定是否修订：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>生成 -&gt; 校验/审查 -&gt; 通过</span></span>
<span class="line"><span>                  -&gt; 修订 -&gt; 再校验</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>适合有明确质量标准的文案、代码或报告。若校验规则完全确定，应优先直接验证并返回错误，不必再调用一个模型“评价”。</p><h3 id="_7-1-审查契约" tabindex="-1">7.1 审查契约 <a class="header-anchor" href="#_7-1-审查契约" aria-label="Permalink to &quot;7.1 审查契约&quot;">​</a></h3><p>审查结果应结构化：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>status: pass | revise | reject</span></span>
<span class="line"><span>issues: [{rule, evidence, location, suggestion}]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>修订次数必须有限。连续修订仍不能通过时，应返回失败或转人工，而不是无限循环消耗 Token。</p><h2 id="_8-模式六-工作流内-agent" tabindex="-1">8. 模式六：工作流内 Agent <a class="header-anchor" href="#_8-模式六-工作流内-agent" aria-label="Permalink to &quot;8. 模式六：工作流内 Agent&quot;">​</a></h2><p>复杂业务常把 Agent 放在确定性工作流的一个局部阶段：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>鉴权 -&gt; 数据准备 -&gt; [Agent 研究与工具选择] -&gt; 业务校验 -&gt; 审批 -&gt; 提交</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>工作流控制不可跳过的业务阶段，Agent 只在开放问题中自主决策。这种混合模式通常比“让一个 Agent 负责全部流程”更容易控制。</p><h3 id="_8-1-边界设计" tabindex="-1">8.1 边界设计 <a class="header-anchor" href="#_8-1-边界设计" aria-label="Permalink to &quot;8.1 边界设计&quot;">​</a></h3><ul><li>Agent 接收精简、已授权的输入；</li><li>Agent 的输出采用 Schema；</li><li>工作流重新校验关键结果；</li><li>副作用由专门节点执行；</li><li>Agent 失败不会绕过审批和事务边界。</li></ul><h2 id="_9-不要过早进入多-agent" tabindex="-1">9. 不要过早进入多 Agent <a class="header-anchor" href="#_9-不要过早进入多-agent" aria-label="Permalink to &quot;9. 不要过早进入多 Agent&quot;">​</a></h2><p>把不同 Prompt 命名为多个 Agent，不会自动提升质量。多 Agent 还会引入任务分配、消息传递、共享状态、终止和责任归属问题。</p><p>本模块聚焦单 Agent 及其局部模式。只有当角色确实需要独立上下文、工具权限或并行生命周期时，才进入“工作流与多 Agent”模块讨论拓扑和协作。</p><h2 id="_10-选择矩阵" tabindex="-1">10. 选择矩阵 <a class="header-anchor" href="#_10-选择矩阵" aria-label="Permalink to &quot;10. 选择矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题特征</th><th>首选模式</th></tr></thead><tbody><tr><td>单次转换、抽取或分类</td><td>直接模型调用</td></tr><tr><td>从有限工具中动态查询或操作</td><td>工具型 Agent</td></tr><tr><td>先选择一个稳定领域分支</td><td>路由</td></tr><tr><td>长目标需要动态拆解和调整</td><td>计划—执行</td></tr><tr><td>结果可按标准反复改进</td><td>审查—修订</td></tr><tr><td>开放推理嵌在严格业务流程中</td><td>工作流内 Agent</td></tr></tbody></table><p>如果同时满足多个特征，先选主控制结构，再把其他能力作为局部步骤。不要把所有模式一次组合进去。</p><h2 id="_11-设计步骤" tabindex="-1">11. 设计步骤 <a class="header-anchor" href="#_11-设计步骤" aria-label="Permalink to &quot;11. 设计步骤&quot;">​</a></h2><h3 id="_11-1-定义结果" tabindex="-1">11.1 定义结果 <a class="header-anchor" href="#_11-1-定义结果" aria-label="Permalink to &quot;11.1 定义结果&quot;">​</a></h3><p>明确最终产物、接受标准和失败形式。没有完成定义，Agent 就无法可靠停止。</p><h3 id="_11-2-列出不确定决策" tabindex="-1">11.2 列出不确定决策 <a class="header-anchor" href="#_11-2-列出不确定决策" aria-label="Permalink to &quot;11.2 列出不确定决策&quot;">​</a></h3><p>找出哪些步骤真的需要语义判断。可以由规则决定的部分保留在应用和工作流中。</p><h3 id="_11-3-限定能力" tabindex="-1">11.3 限定能力 <a class="header-anchor" href="#_11-3-限定能力" aria-label="Permalink to &quot;11.3 限定能力&quot;">​</a></h3><p>只提供当前任务所需工具，定义每个工具的输入、输出、错误和副作用等级。</p><h3 id="_11-4-设计状态和上下文" tabindex="-1">11.4 设计状态和上下文 <a class="header-anchor" href="#_11-4-设计状态和上下文" aria-label="Permalink to &quot;11.4 设计状态和上下文&quot;">​</a></h3><p>区分 State、Runtime Context、Store 和业务数据，决定模型每轮实际看到什么。</p><h3 id="_11-5-设置预算与停止条件" tabindex="-1">11.5 设置预算与停止条件 <a class="header-anchor" href="#_11-5-设置预算与停止条件" aria-label="Permalink to &quot;11.5 设置预算与停止条件&quot;">​</a></h3><p>限制模型调用、工具调用、总时间、成本和修订次数。停止原因必须可观察。</p><h3 id="_11-6-建立基线和评估" tabindex="-1">11.6 建立基线和评估 <a class="header-anchor" href="#_11-6-建立基线和评估" aria-label="Permalink to &quot;11.6 建立基线和评估&quot;">​</a></h3><p>先用直接调用或固定工作流建立基线，再证明 Agent 模式在任务成功率上带来的收益足以覆盖成本和风险。</p><h2 id="_12-评估维度" tabindex="-1">12. 评估维度 <a class="header-anchor" href="#_12-评估维度" aria-label="Permalink to &quot;12. 评估维度&quot;">​</a></h2><p>模式选择应由数据验证：</p><ul><li>任务完成率与关键字段正确率；</li><li>工具选择和参数正确率；</li><li>未授权或重复副作用次数；</li><li>平均及尾部延迟；</li><li>模型、工具和人工成本；</li><li>可解释失败比例；</li><li>同一输入的稳定性。</li></ul><p>只展示几次成功 Demo 无法证明一个模式适合生产。</p><h2 id="_13-反模式" tabindex="-1">13. 反模式 <a class="header-anchor" href="#_13-反模式" aria-label="Permalink to &quot;13. 反模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>反模式</th><th>典型表现</th><th>修正</th></tr></thead><tbody><tr><td>万能 Agent</td><td>一个 Agent 拥有所有工具和数据</td><td>按任务缩小能力面</td></tr><tr><td>Prompt 状态机</td><td>用长提示词描述严格流程</td><td>使用显式工作流</td></tr><tr><td>无停止条件</td><td>让模型自行判断“直到完成”</td><td>设置可验证结果与预算</td></tr><tr><td>自我审查即安全</td><td>让同一模型确认自身操作</td><td>确定性校验和独立审批</td></tr><tr><td>多 Agent 角色扮演</td><td>只换系统提示词，没有真实边界</td><td>保留单 Agent 或建立独立职责</td></tr></tbody></table><h2 id="_14-结论" tabindex="-1">14. 结论 <a class="header-anchor" href="#_14-结论" aria-label="Permalink to &quot;14. 结论&quot;">​</a></h2><p>Agent 设计的本质是分配控制权。把确定性业务规则留给代码和工作流，把需要语义判断的局部选择交给模型，再用状态、上下文、预算和 Guardrails 限定它。模式越复杂，越需要用评估证明其必要性。</p><h2 id="_15-延伸阅读" tabindex="-1">15. 延伸阅读 <a class="header-anchor" href="#_15-延伸阅读" aria-label="Permalink to &quot;15. 延伸阅读&quot;">​</a></h2><ul><li><a href="https://docs.langchain.com/oss/python/langchain/agents" target="_blank" rel="noreferrer">LangChain Agents</a></li><li><a href="https://docs.langchain.com/oss/python/langchain/context-engineering" target="_blank" rel="noreferrer">LangChain Context Engineering</a></li><li><a href="https://docs.langchain.com/oss/python/langchain/middleware/overview" target="_blank" rel="noreferrer">LangChain Middleware</a></li></ul>`,88)])])}const u=a(l,[["render",d]]);export{g as __pageData,u as default};
